using System.IO.Compression;using Orbit.Core;
static class ShaderChecks {
 public static int Run(string root){try{RunAsync(root).GetAwaiter().GetResult();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static async Task RunAsync(string root){using var client=new ModrinthClient();var cats=await client.CategoriesAsync(projectType:"shader");if(cats.Count==0)throw new Exception("Shader categories missing");Console.WriteLine("PASS live shader categories");var search=await client.SearchAsync("complementary","1.21.1",null,"",0,"relevance",projectType:"shader");if(search.Projects.Count==0)throw new Exception("No shaders found");Console.WriteLine("PASS live shader search");var plan=await client.ResolveAsync(search.Projects[0].Id,"1.21.1","iris",projectType:"shader");if(plan.ContentFolder!="shaderpacks"||plan.Files.Any(f=>!f.Filename.EndsWith(".zip",StringComparison.OrdinalIgnoreCase)))throw new Exception("Wrong shader plan");Console.WriteLine("PASS compatible Iris/OptiFine ZIP plan");await client.InstallAsync(plan,root);foreach(var f in plan.Files){using var zip=ZipFile.OpenRead(Path.Combine(root,"shaderpacks",f.Filename));if(!zip.Entries.Any(e=>e.FullName.StartsWith("shaders/")))throw new Exception("Missing shaders directory");}if(Directory.Exists(Path.Combine(root,"mods"))||Directory.Exists(Path.Combine(root,"resourcepacks")))throw new Exception("Wrong installation folder");Console.WriteLine("PASS real shader CDN install, SHA512 and ZIP layout");await client.InstallAsync(plan,root);Console.WriteLine("PASS repeated shader installation");if(!File.Exists(Path.Combine(root,".orbit/modrinth-shaders.json")))throw new Exception("Missing shader manifest");Console.WriteLine("PASS separate shader manifest; no game launched");}
}
